cat > /tmp/sw/show.py <<'EOF'
import sys
data = sys.stdin.buffer.read()
try:
    t = data.decode('utf-8')
except UnicodeDecodeError:
    t = data.decode('utf-8','replace')
lines = t.split('\n')
if lines and lines[-1]=='' : lines=lines[:-1]; trail=True
else: trail=False
for i,l in enumerate(lines):
    out=[]
    for ch in l:
        o=ord(ch)
        if o<32 or o==127: out.append('\\x%02x'%o)
        elif o==27: out.append('\\e')
        else: out.append(ch)
    s=''.join(out)
    print('%3d|%s|len=%d'%(i+1,s,len(l)))
if not trail: print('(NO trailing newline on last line)')
else: print('(ends with newline)')
EOF
cat > /tmp/sw/cp.py <<'EOF'
import sys,unicodedata
t=sys.stdin.buffer.read().decode('utf-8','replace')
for line in t.split('\n'):
    parts=[]
    for ch in line:
        parts.append('U+%04X(%s)'%(ord(ch), unicodedata.name(ch,'?')) if ord(ch)>127 else repr(ch))
    print(' '.join(parts))
EOF
